<script setup lang="ts">
import {computed} from 'vue'
import Portrait from './Portrait.vue'
import ReviewUnit from './ReviewUnit.vue'
import {useStudio} from './studioContext'
import {profile,instanceName} from './people'
import {selectedFigure,type VisualCard} from './visualGroups'
const props=defineProps<{project:any,card:VisualCard,selected:string}>(),emit=defineEmits<{select:[id:string]}>(),s=useStudio()
const active=computed(()=>selectedFigure(props.card,props.selected)),role=computed(()=>props.project.characters.find((c:any)=>c.id===props.card.characterId))
const stack=computed(()=>[...props.card.members.filter(a=>a.id!==active.value.id).slice(0,2),active.value])
const shared=computed(()=>s.rec('material','main').draft.visualGroups?.[props.card.characterId]?.description||'')
const groupRoles=computed(()=>props.project.characters.filter((c:any)=>c.roleType==='group'))
function editShared(value:string){const mat=s.rec('material','main').draft;mat.visualGroups||={};mat.visualGroups[props.card.characterId]={description:value,kind:'creator_note'};s.scheduleAutosave()}
function linkGroup(cid:string){for(const a of props.card.members){a.characterId=cid;a.identityManual=true;const match=props.project.matches.find((m:any)=>m.annotationId===a.id);if(match){match.characterId=cid;match.manual=true;match.stale=false}}s.scheduleAutosave()}
function observations(a:any){return props.project.observations.filter((o:any)=>o.annotationId===a.id)}
function matching(a:any){return props.project.matches.find((m:any)=>m.annotationId===a.id)}
const locked=computed(()=>props.card.members.some(a=>s.rootLocked('/annotations/@'+a.id,true))||s.locked('material','main','visualGroups'))
</script>
<template><section :id="'person-group-'+card.characterId" class="group-visual-card" :class="{chosen:card.members.some(a=>a.id===selected)}" :aria-label="role?.name+'群体卡片'" @click="emit('select',active.id)"><header><div class="card-stack" aria-label="群体叠放卡片"><div v-for="(a,i) in stack" :key="a.id" class="mini-card" :style="{transform:`translate(${(i-stack.length+1)*7}px,${(stack.length-i-1)*4}px) rotate(${(i-stack.length+1)*-5}deg)`,zIndex:i}"><Portrait :url="project.image" :box="a"/></div></div><div class="group-heading"><span class="group-kicker">共享角色</span><h3>{{role?.name}}</h3><span>{{card.members.length}} 个画中身影 · 一次确认</span></div></header><label>共用角色<select :value="card.characterId" :disabled="locked" @click.stop @change="linkGroup(($event.target as HTMLSelectElement).value)"><option v-for="c in groupRoles" :key="c.id" :value="c.id">{{c.name}}</option></select></label><p class="group-profile">{{profile(role)}}</p><nav class="figure-selector" :aria-label="role?.name+'的画中身影'" @click.stop><button v-for="(a,i) in card.members" :key="a.id" :aria-label="'选择'+instanceName(project,a)+'的位置框'" :aria-pressed="active.id===a.id" :class="{active:active.id===a.id}" @click="emit('select',a.id)">{{i+1}}</button></nav><p class="frame-caption">正在查看 {{instanceName(project,active)}} · 在左侧画作中调整此身影的位置框</p><ReviewUnit :unit-id="card.id" label="确认此群体"/><details @click.stop><summary>共用补充说明（选填）</summary><textarea :value="shared" :disabled="locked" rows="3" placeholder="填写整组共用的说明；不同衣饰和动作的旧观察保留在下方。" aria-label="群体共用补充说明" @input="editShared(($event.target as HTMLTextAreaElement).value)"/><small>共用说明与位置分别保存，不会覆盖原有逐人观察。</small></details><details v-if="role?.mentions?.length" @click.stop><summary>共用原文依据</summary><p v-for="m in role.mentions"><q>{{m.quote}}</q></p></details><details @click.stop><summary>原有画面观察与匹配依据</summary><div v-for="a in card.members" :key="a.id" class="original-observation"><b>{{instanceName(project,a)}}</b><p>{{a.description||'未记录单独描述'}}</p><p v-for="o in observations(a)"><span v-if="o.description&&o.description!==a.description">{{o.description}}</span><small v-if="o.inference">视觉推测：{{o.inference}}</small></p><small v-if="matching(a)">{{matching(a).reason}}</small></div></details></section></template>
<style scoped>.group-visual-card{position:relative;border:1px solid #d5ded8;border-radius:12px;padding:22px 18px 18px;margin:12px 8px 24px;background:#f7faf7;box-shadow:0 4px 0 -1px #edf3ee,0 5px 0 #d5ded8,0 9px 0 -1px #f3f6f3,0 10px 0 #dde4de}.group-visual-card.chosen{outline:2px solid #568f9f;outline-offset:2px}.group-visual-card header{display:flex;gap:18px;align-items:center;margin-bottom:18px}.card-stack{width:92px;height:114px;position:relative;flex-shrink:0;margin-left:10px}.mini-card{position:absolute;inset:0;background:#fff;border:3px solid #fff;border-radius:9px;box-shadow:0 1px 6px #27392b25;overflow:hidden;pointer-events:none}.mini-card :deep(canvas){height:100%;width:100%;max-height:none;object-fit:contain}.group-kicker{font-size:10px;letter-spacing:.08em;color:#87968d}.group-heading h3{font-size:20px;margin:6px 0}.group-heading>span:last-child{font-size:12px;color:#7b8b80}.group-profile{font-size:13px;line-height:1.8;color:#637469;margin:12px 0}.figure-selector{display:flex;gap:6px;flex-wrap:wrap;margin-top:16px}.figure-selector button{min-width:32px;min-height:32px;padding:5px 9px;font-size:12px;border-color:#dae2dc;background:#fff;color:#75877b}.figure-selector button.active{background:#377e70;border-color:#377e70;color:#fff}.frame-caption{font-size:11px;line-height:1.7;color:#819086}.group-visual-card label{font-size:12px}.group-visual-card select{font-size:13px;margin-top:5px}.group-visual-card details{font-size:12px;margin-top:12px;color:#77867b}.group-visual-card summary{cursor:pointer}.group-visual-card textarea{font-size:13px;margin-top:10px}.group-visual-card small{font-size:11px;display:block;line-height:1.7}.original-observation{padding:12px 0;border-bottom:1px solid #e4eae4}.original-observation p{white-space:pre-wrap;line-height:1.8;margin:6px 0}</style>
